function PARITY-DATA(n, k):
    bits <- empty list
    x <- n
    for j = 0 to k-1:
        b <- x mod 2
        append b to bits
        if b = 0 then x <- x / 2 else x <- (3x + 1) / 2
    word <- 0 ; ones <- 0
    for j = 0 to k-1:
        word <- word + bits[j] * 2^j
        ones <- ones + bits[j]
    return (bits, word, ones, x)      // x = T^k(n)

function PARITY-TRANSFORM(k):
    N <- 2^k
    for n = 0 to N-1:
        words[n] <- second component of PARITY-DATA(n, k)
    for j = 0 to N-1:
        acc <- 0 + 0i
        for n = 0 to N-1:
            acc <- acc + exp(2*pi*i * j * words[n] / N)
        out[j] <- |acc|
    return out            // out[0] = N, out[j] = 0 for j != 0

