import math

THETA: float = math.log(2.0) / math.log(3.0)   # critical odd-step density
DELTA: float = THETA - 0.5                     # spectral margin


def noncontracting_density(k: int) -> float:
    """rho_k: the density of residues mod 2^k failing to contract in k steps.

    A class fails exactly when 3^{s_k(n)} >= 2^k, i.e. s_k(n) >= k*theta.  Since
    the odd-step count is EXACTLY Binomial(k, 1/2) over residues, rho_k is a pure
    binomial tail:

        rho_k = 2^{-k} * sum_{s >= ceil(k theta)} C(k, s).

    Complexity: O(k) big-integer operations -- no enumeration of the 2^k
    residues is needed, which is the practical payoff of the exact spectral gap.
    """
    smin = math.ceil(k * THETA)
    return sum(math.comb(k, s) for s in range(smin, k + 1)) / float(1 << k)


def chebyshev_bound(k: int) -> float:
    """Proved bound 1/(4 delta^2 k), from the exact variance k/4."""
    return 1.0 / (4.0 * DELTA * DELTA * k)


def chernoff_bound(k: int) -> float:
    """Proved bound (243/256)^{k/5}, from the exponential moment at tilt x = 2."""
    return (243.0 / 256.0) ** (k / 5.0)


def sharp_rate(k: int) -> float:
    """Conjectured optimal rate exp(-k D(theta || 1/2)) at tilt theta/(1-theta)."""
    d = THETA * math.log(2 * THETA) + (1 - THETA) * math.log(2 * (1 - THETA))
    return math.exp(-k * d)

