function CERTIFY-DESCENT(n, k):
    r <- n mod 2^k
    s <- odd-step count of PARITY-DATA(r, k)
    if 3^s >= 2^k:
        return (FALSE, "expanding class: slope >= 1")
    if n < 8^k:
        return (FALSE, "contracting class but below the proved threshold")
    return (TRUE, "T^k(n) < n, certified by the transport formula")
